    this.mqttSubscribe(`${ns}/+/StatusStateAttribute/value`, (m) => this._onVacStatus(m.topic, "value", m.payloadString));
    this.mqttSubscribe(`${ns}/+/StatusStateAttribute/flag`, (m) => this._onVacStatus(m.topic, "flag", m.payloadString));
